#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <string>
#include "cJSON.h"
#include "lodepng.h"

// Forward declaration helpers
static std::vector<double> parse_floats(cJSON* arr) {
    std::vector<double> v;
    if (!arr || !cJSON_IsArray(arr)) return v;
    cJSON* it;
    cJSON_ArrayForEach(it, arr) {
        if (cJSON_IsNumber(it)) v.push_back(it->valuedouble);
        else v.push_back(0.0);
    }
    return v;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: cli_tool weights.json image.png\n");
        return 1;
    }

    // ---- Load weights.json ----
    FILE* f = fopen(argv[1], "rb");
    if (!f) { fprintf(stderr, "cannot open weights file\n"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    rewind(f);
    std::string buf;
    buf.resize(sz);
    fread(&buf[0], 1, sz, f);
    fclose(f);

    cJSON* root = cJSON_Parse(buf.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    std::vector<double> w_in = parse_floats(cJSON_GetObjectItem(root, "input_weight"));
    std::vector<double> b_in = parse_floats(cJSON_GetObjectItem(root, "input_bias"));
    std::vector<double> w_h  = parse_floats(cJSON_GetObjectItem(root, "hidden_weight"));
    std::vector<double> b_h  = parse_floats(cJSON_GetObjectItem(root, "hidden_bias"));
    std::vector<double> w_o  = parse_floats(cJSON_GetObjectItem(root, "output_weight"));
    std::vector<double> b_o  = parse_floats(cJSON_GetObjectItem(root, "output_bias"));

    const int H = 16;       // hidden dim
    const int IN = 784;     // 28x28
    const int OUT = 10;
    (void)IN; (void)OUT;

    // ---- Load image with lodepng ----
    unsigned imgw=0, imgh=0;
    std::vector<unsigned char> image;
    unsigned err = lodepng::decode(image, imgw, imgh, argv[2], LCT_GREY);
    if (err) { fprintf(stderr, "png decode error: %s\n", lodepng_error_text(err)); return 1; }

    if (imgw != 28 || imgh != 28) {
        fprintf(stderr, "expected 28x28 image, got %ux%u\n", imgw, imgh);
        return 1;
    }

    // ---- Build features (MNIST normalization) ----
    std::vector<double> x(784);
    const double mean = 0.1307;
    const double std_ = 0.3081;
    for (int i = 0; i < 784; i++) {
        x[i] = (double(image[i]) / 255.0 - mean) / std_;
    }

    // ---- Forward pass ----
    auto relu = [](double v){ return v > 0.0 ? v : 0.0; };

    std::vector<double> h1(16, 0.0);
    for (int j = 0; j < 16; j++) {
        double acc = b_in[j];
        for (int i = 0; i < 784; i++) acc += w_in[j*784 + i] * x[i];
        h1[j] = relu(acc);
    }

    std::vector<double> h2(16, 0.0);
    for (int j = 0; j < 16; j++) {
        double acc = b_h[j];
        for (int i = 0; i < 16; i++) acc += w_h[j*16 + i] * h1[i];
        h2[j] = relu(acc);
    }

    std::vector<double> out(10, 0.0);
    for (int k = 0; k < 10; k++) {
        double acc = b_o[k];
        for (int i = 0; i < 16; i++) acc += w_o[k*16 + i] * h2[i];
        out[k] = acc;
    }

    int pred = 0;
    for (int k = 1; k < 10; k++) if (out[k] > out[pred]) pred = k;

    printf("%d\n", pred);

    cJSON_Delete(root);
    return 0;
}

